function card(item){const rows=points(item.id),last=rows.at(-1),prev=rows.at(-2),stale=last&&age(last.date)>item.staleDays;let delta='이전 관측값 없음';if(prev)delta=diffText(last,prev,item.unit)+' <small>'+primaryLabel(item.frequency,item.id)+'</small>';const compares=last?compareList(rows,item):[];const latestRun=payload.db.runs.at(-1)?.results.find(r=>r.ids?.includes(item.id));const failed=latestRun&&!latestRun.ok;return `<article class="card" data-id="${item.id}" data-group="${esc(item.group)}"><div class="card-top"><div><h3>${esc(item.name)}</h3></div><span class="tools"><button class="star${isCore(item.id)?' on':''}" data-star="${item.id}" aria-pressed="${isCore(item.id)}" title="${isCore(item.id)?'핵심 지표에서 빼기':'핵심 지표에 추가'}" aria-label="${esc(item.name)} 핵심 지표 ${isCore(item.id)?'해제':'추가'}">${isCore(item.id)?'★':'☆'}</button><button class="tool" data-copy="img" title="그래프 이미지 복사 (PPT·엑셀·메일에 Ctrl+V)" aria-label="${esc(item.name)} 그래프 이미지 복사">복사</button><button class="tool" data-copy="png" title="PNG 파일로 저장" aria-label="${esc(item.name)} PNG 저장">PNG</button><button class="tool" data-copy="tsv" title="표시 구간 데이터 복사 (엑셀 붙여넣기)" aria-label="${esc(item.name)} 데이터 복사">데이터</button></span><button class="expand" data-expand="${item.id}" aria-label="${esc(item.name)} 확대">⤢</button><span class="badge ${!last||stale||failed?'warn':''}">${!last?'연결 대기':failed?'수집 오류':stale?'발표/갱신 확인':item.frequency}</span></div><div class="metric"><span class="value">${last?n(last.value):'—'}</span><span class="unit">${esc(item.unit)}</span><span class="change ${last&&prev&&last.value>prev.value?'rise':'fall'}">${delta}</span></div><div class="date">${last?finalLine(last,prev,item):'필요 원천: '+esc(item.sourceHint||'원천 연결 확인 중')}</div><div class="compare">${compares.map(c=>`<span class="${c.cls}" title="${esc(dlab(c.from,item))} 대비"><small>${c.label}</small> ${c.text}</span>`).join('')}</div>${item.id==='tariff_smp'?kBlock():`<div class="chart">${chart(rows,item)}</div>${legend(rows,item)}`}<div class="stock-tags">${[...new Set(item.effects.flatMap(e=>e.codes))].map(c=>esc(payload.stocks[c])).join(' · ')}</div><details class="impact"><summary>실적 영향 · 시차 · 출처</summary><div class="history"><span>${rows.length.toLocaleString()}개 관측${period&&last&&Date.parse(rows[0].date)>cutoff()+45*86400000?' · 선택 기간 일부':''}</span><span>${last?rows[0].date+' ~ '+last.date:'미수집'}</span></div><p class="definition">${esc(item.definition)}</p>${item.effects.map(e=>`<div class="effect"><div>${e.codes.map(c=>`<b>${esc(payload.stocks[c]||c)}</b><small>${c}</small>`).join('')}</div><div>${e.direction?`<p class="direction-strip"><span class="direction ${e.direction.up}">상승: ${e.direction.up}</span> <span class="direction ${e.direction.down}">하락: ${e.direction.down}</span><small> 조건부 실적 영향</small></p>`:""}<p>${esc(e.text)}</p><div class="lag">시차 · ${esc(e.lag)} ${(e.auditSources||[payload.sources[e.ref]]).map((s,i)=>`<a href="${esc(s.url)}" target="_blank" rel="noopener" title="${esc(s.title||s.name)}">근거 ${i+1} ↗</a>`).join(" · ")} ${e.analysisUrl?`<a href="${esc(e.analysisUrl)}">주가 시차·수치 비교 →</a>`:""}</div></div></div>`).join('')}<div class="source"><span>${last?esc(last.source):'미수집'}${last?' · 수집 '+esc(stamp(last.collectedAt)):''}</span>${last?`<a href="${esc(last.url)}" target="_blank" rel="noopener">원문 ↗</a>`:''}</div></details></article>`;}
function renderOilCurve(){const c=payload.oilCurve;const el=$('oil-curve');if(!el)return;if(!c||!c.wti?.length){el.innerHTML='<p class="muted">월물 커브 미수집</p>';return;}
 const months=[...new Set([...c.wti,...c.brent].map(x=>x.contract))].sort();const w0=c.wti[0]?.price,b0=c.brent[0]?.price;const cell=(list,base)=>m=>{const x=list.find(y=>y.contract===m);if(!x)return '<td class="num">–</td>';const d=x.price-base;return `<td class="num">${x.price.toFixed(2)}<small> ${d>0?'+':''}${d.toFixed(2)}</small></td>`;};
 const slope=(list)=>{const f=list[0],t=list.find(x=>x.contract>=f.contract.replace(/^(\d{4})/,(_,y)=>String(Number(y)+1)))||list.at(-1);return f&&t?`${f.contract} ${f.price.toFixed(2)} → ${t.contract} ${t.price.toFixed(2)} (${((t.price/f.price-1)*100).toFixed(1)}%, ${t.price<f.price?'백워데이션':'콘탱고'})`:'';};
 el.innerHTML=`<p><b>WTI</b> ${slope(c.wti)} · <b>Brent</b> ${slope(c.brent)} · 조회 ${esc(c.asOf.slice(0,16).replace('T',' '))} UTC</p><div class="table-wrap"><table><thead><tr><th>월물</th>${months.map(m=>`<th>${m.slice(2).replace('-','/')}</th>`).join('')}</tr></thead><tbody><tr><td>WTI (USD/bbl)</td>${months.map(cell(c.wti,w0)).join('')}</tr><tr><td>Brent (USD/bbl)</td>${months.map(cell(c.brent,b0)).join('')}</tr></tbody></table></div><p class="muted">작은 숫자는 최근월 대비 차이. 출처 Yahoo Finance 개별 월물(CL·BZ, .NYM), 장중 가격 포함.</p>`;}
function render(){ renderOilCurve(); $('history-coverage').innerHTML=payload.catalog.map(c=>{const r=points(c.id);return '<tr><td>'+esc(c.name)+'</td>'+[3653,1826,1096,366].map(d=>'<td>'+n(r.filter(x=>Date.parse(x.date)>=cutoff(d)).length,0)+'</td>').join('')+'<td>'+(r.length?r[0].date+' ~ '+r.at(-1).date:'미수집')+'</td></tr>';}).join('');$('period-buttons').innerHTML=[[3653,'10년'],[1826,'5년'],[1096,'3년'],[366,'1년']].map(([v,label])=>'<button data-period="'+v+'" aria-pressed="'+(period===v)+'" class="'+(period===v?'active':'')+'">'+label+'</button>').join('');$('period-buttons').querySelectorAll('button').forEach(b=>b.onclick=()=>{period=Number(b.dataset.period);$('period').value=String(period);render();});const opened=[...document.querySelectorAll('#cards .card details[open],#pending-cards .card details[open]')].map(d=>d.closest('.card').dataset.id);const available=payload.catalog.filter(c=>points(c.id).length).length;const lastRun=payload.db.runs.at(-1);$('updated').innerHTML=`${new Date().toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric'})}<br>마지막 공개원천 확인 ${esc(stamp(lastRun?.at))}`;
 $('coverage').textContent=`${available}개 지표 수집 · ${payload.catalog.reduce((a,c)=>a+(payload.db.series[c.id]?.length||0),0).toLocaleString()}개 실제 관측값 · 매일 자동 갱신`;
 $('tabs').innerHTML=['전체','핵심','복합 그래프','에너지','유가','전력·요금','수요·가동','금리·환율','상사·원자재','해외·일본','해외·미국'].map(g=>`<button data-group="${g}" class="${group===g?'active':''}">${g==='핵심'?'★ 핵심 '+coreSet().size:g}</button>`).join('')+(group==='핵심'?'<button id="core-clear" class="core-reset" title="핵심 지표를 모두 해제하고 ★로 새로 고르기">모두 해제</button><button id="core-reset" class="core-reset" title="핵심 지표를 기본 목록으로 되돌림">기본값 복원</button>':'');$('tabs').querySelectorAll('button[data-group]').forEach(b=>b.onclick=()=>{group=b.dataset.group;render();});const cc=$('core-clear');if(cc)cc.onclick=()=>{if(confirm('핵심 지표를 모두 해제할까요? 이후 전체 탭에서 ★로 고르면 됩니다.')){coreSet().clear();saveCore();render();}};const cr=$('core-reset');if(cr)cr.onclick=()=>{if(confirm('핵심 지표 선택을 기본 목록으로 되돌릴까요?')){resetCore();render();}};
 const filtered=payload.catalog.filter(c=>c.id!=='tariff_smp'&&(group==='전체'||group==='핵심'&&isCore(c.id)||c.group===group||(c.tabs||[]).includes(group))&&(!stock||c.effects.some(e=>e.codes.includes(stock))));filtered.sort((a,b)=>Number(!!points(b.id).length)-Number(!!points(a.id).length));$('cards').innerHTML=(stock?linkSection():linkMatrix())+panelSection()+['에너지','유가','전력·요금','수요·가동','금리·환율','상사·원자재','해외·일본','해외·미국'].map(g=>{const cs=filtered.filter(c=>c.group===g&&points(c.id).length);cs.sort((a,b)=>Number(points(b.id).length>1)-Number(points(a.id).length>1));return cs.length?'<section><div class="section-head"><h2>'+g+'</h2><span>'+cs.length+'개 지표</span></div><div class="grid">'+cs.map(card).join('')+'</div></section>':'';}).join('');if(group==='핵심'&&!coreSet().size)$('cards').innerHTML='<p class="notice">핵심 지표가 비어 있습니다. 전체 탭에서 카드 오른쪽 위 ☆를 눌러 추가하세요. 선택은 이 브라우저에 저장됩니다.</p>';const pending=filtered.filter(c=>!points(c.id).length);$('pending-title').textContent='연결 대기 지표 · '+pending.length+'개';$('pending-cards').innerHTML=pending.map(card).join('');document.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>{const c=payload.catalog.find(c=>c.id===b.dataset.expand);$('detail-title').textContent=c.name;$('detail-body').innerHTML=card(c);$('detail-body').querySelector('[data-expand]').remove();$('detail-body').querySelector('details').open=true;$('detail').showModal();});table();
 $('notice').textContent=`${filtered.filter(c=>points(c.id).length).length}개 차트 · 뱃지는 직전 관측 대비(전일/전월/전년), 아래 칩은 1W·1M·3M·1Y 변화율(%p·°C 지표는 차이, 스프레드는 $ 차이) · 색상은 주가 전망이 아닙니다.`;
 $('sources').innerHTML=payload.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)} ↗</a>`).join('');
 $('health').innerHTML=(lastRun?.results||[]).map(r=>`<div class="health-row"><b>${esc(r.name)}</b><span>${r.ok?'정상 · '+r.count+'개 관측값':'실패 · '+esc(r.error)}</span></div>`).join('')+`<div class="health-row"><b>BigFinance</b><span>${payload.monitor?esc(stamp(payload.monitor.checkedAt))+' · '+esc(payload.monitor.note):'자동 확인 기록 없음 · 로그인 세션 필요'}</span></div>`;
 for(const d of document.querySelectorAll('.card details'))if(opened.includes(d.closest('.card').dataset.id))d.open=true; $('ids').textContent=payload.catalog.map(c=>`${c.id} → ${c.name} (${c.unit})`).join('\n');}
async function load(){const r=await fetch('/api/data');if(!r.ok)throw Error('로컬 데이터 읽기 실패');const next=await r.json();payload=next;if(!$('data-series').options.length)for(const c of payload.catalog)$('data-series').add(new Option(c.name,c.id));if($('stock').options.length===1){const gs=payload.globalStocks||{},grp=(label,list)=>{if(!list.length)return;const og=document.createElement('optgroup');og.label=label;for(const [code,name] of list)og.appendChild(new Option(name,code));$('stock').appendChild(og);};grp('국내 커버리지',Object.entries(payload.stocks).filter(([c])=>!gs[c]));for(const sec of [...new Set(Object.values(gs).map(v=>v.sector))])grp(sec,Object.entries(gs).filter(([,v])=>v.sector===sec).map(([c,v])=>[c,v.name]));}{const qs=new URLSearchParams(location.search).get('stock');if(qs&&payload.stocks[qs]&&!stock){stock=qs;$('stock').value=qs;}}render();}
 $('stock').onchange=e=>{stock=e.target.value;render();};$('period').onchange=e=>{period=Number(e.target.value);render();};$('refresh').onclick=async()=>{const b=$('refresh');b.disabled=true;b.textContent='공개 원천 확인 중…';try{const r=await fetch('/api/refresh',{method:'POST'});if(!r.ok)throw Error((await r.json()).error);await load();}catch(e){$('notice').textContent=e.message;}finally{b.disabled=false;b.textContent='공개 데이터 갱신 ↻';}};
 $('import').onclick=async()=>{const f=$('csv').files[0];if(!f){$('notice').textContent='CSV 파일을 선택하세요.';return;}try{const r=await fetch('/api/import',{method:'POST',headers:{'Content-Type':'text/csv'},body:await f.text()});const j=await r.json();if(!r.ok)throw Error(j.error);await load();$('notice').textContent=`${j.count}개 관측값 반영 완료`;}catch(e){$('notice').textContent=e.message;}};
load().catch(e=>{$('notice').textContent=e.message;});

