function pAgg(rows,key){const g=new Map();for(const r of rows){const k=key(r.date);(g.get(k)||g.set(k,[]).get(k)).push(r.value);}return [...g].map(([k,v])=>({k,value:v.reduce((a,b)=>a+b,0)/v.length}));}
