  if(s.type==='mstep')segs=pAgg(rows,d=>d.slice(0,7)).map(x=>({a:mStart(x.k),b:mEnd(x.k),value:x.value}));
  if(s.type==='qstep')segs=pAgg(rows,qKey).map(x=>({a:qStart(x.k),b:qEnd(x.k),value:x.value}));
