 const span=(x1-x0)/864e5,stepM=span>2900?12:span>1100?6:span>500?3:span>200?2:1;const d=new Date(x0);d.setUTCDate(1);d.setUTCMonth(Math.ceil(d.getUTCMonth()/stepM)*stepM);
 for(;d.getTime()<=x1;d.setUTCMonth(d.getUTCMonth()+stepM)){const t=d.getTime();if(t<x0)continue;const x=X(t);g+=`<line x1="${x}" x2="${x}" y1="${T}" y2="${T+ph}" class="gridline"/><text x="${x}" y="${T+ph+14}" class="p-xtick" text-anchor="middle">${stepM>=12?d.getUTCFullYear():String(d.getUTCFullYear()).slice(2)+'.'+String(d.getUTCMonth()+1).padStart(2,'0')}</text>`;}
